#!/usr/bin/env node

/*
 * Deterministic vector source for Chapter 2 report figures.
 *
 * The palette, typography, cards, arrows, and 16:9 canvas follow the
 * visual language established by the Chapter 1 figures. Figures 2.2 and
 * 2.3 are emitted as editable SVGs and publication-ready PNGs. Figures
 * 2.1 and 2.4 are manually refined FigJam flowcharts with editable SVG
 * exports and are not generated by this script.
 */

const fs = require("node:fs");
const path = require("node:path");
const crypto = require("node:crypto");
const sharp = require("sharp");

const OUT = __dirname;
const W = 1600;
const H = 900;

const C = {
  bg: "#FEFEFE",
  navy: "#0F2D4E",
  navy2: "#173E67",
  teal: "#0A8C86",
  teal2: "#2D9D96",
  tealPale: "#DDF3F1",
  amber: "#DA902D",
  amberPale: "#FCE9CF",
  red: "#D84A49",
  redPale: "#FBE3E3",
  violet: "#4D60D6",
  violetPale: "#E8EAFE",
  slate: "#60788E",
  border: "#A8BAC9",
  card: "#F1F5F8",
  card2: "#E9F0F5",
  white: "#FFFFFF",
};

function esc(value) {
  return String(value)
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;");
}

function tspans(lines, x, lineHeight = 1.18) {
  const values = Array.isArray(lines) ? lines : [lines];
  return values
    .map((line, index) => {
      const dy = index === 0 ? 0 : `${lineHeight}em`;
      return `<tspan x="${x}" dy="${dy}">${esc(line)}</tspan>`;
    })
    .join("");
}

function text(x, y, lines, options = {}) {
  const {
    size = 26,
    weight = 700,
    fill = C.navy,
    anchor = "middle",
    lineHeight = 1.18,
    italic = false,
    letterSpacing = 0,
  } = options;
  return `<text x="${x}" y="${y}" text-anchor="${anchor}" font-family="Arial, Helvetica, sans-serif" font-size="${size}" font-weight="${weight}" fill="${fill}" font-style="${italic ? "italic" : "normal"}" letter-spacing="${letterSpacing}" text-rendering="geometricPrecision">${tspans(lines, x, lineHeight)}</text>`;
}

function card(x, y, w, h, options = {}) {
  const {
    fill = C.card,
    stroke = C.border,
    strokeWidth = 2.5,
    radius = 18,
    shadow = true,
    dash = "",
  } = options;
  return `<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="${radius}" fill="${fill}" stroke="${stroke}" stroke-width="${strokeWidth}"${dash ? ` stroke-dasharray="${dash}"` : ""}${shadow ? ' filter="url(#shadow)"' : ""}/>`;
}

function pill(x, y, w, h, label, color, pale, options = {}) {
  const { size = 22, icon = "" } = options;
  return [
    card(x, y, w, h, { fill: pale, stroke: color, strokeWidth: 2, radius: h / 2, shadow: false }),
    icon ? statusIcon(x + 28, y + h / 2, 18, color, icon) : "",
    text(x + (icon ? 51 : w / 2), y + h / 2 + 8, label, {
      size,
      weight: 700,
      fill: color,
      anchor: icon ? "start" : "middle",
    }),
  ].join("");
}

function statusIcon(cx, cy, r, color, kind = "check") {
  const mark =
    kind === "check"
      ? `<path d="M ${cx - 8} ${cy} l 6 7 l 12 -15" fill="none" stroke="#fff" stroke-width="5" stroke-linecap="round" stroke-linejoin="round"/>`
      : kind === "x"
        ? `<path d="M ${cx - 7} ${cy - 7} l 14 14 M ${cx + 7} ${cy - 7} l -14 14" fill="none" stroke="#fff" stroke-width="5" stroke-linecap="round"/>`
        : `<path d="M ${cx} ${cy - 9} v 11 M ${cx} ${cy + 9} v 1" fill="none" stroke="#fff" stroke-width="5" stroke-linecap="round"/>`;
  return `<circle cx="${cx}" cy="${cy}" r="${r}" fill="${color}"/>${mark}`;
}

function arrow(x1, y1, x2, y2, color = C.teal, width = 6, marker = "arrowTeal", dash = "") {
  return `<path d="M ${x1} ${y1} L ${x2} ${y2}" fill="none" stroke="${color}" stroke-width="${width}" stroke-linecap="round"${dash ? ` stroke-dasharray="${dash}"` : ""} marker-end="url(#${marker})"/>`;
}

function pathArrow(d, color = C.teal, width = 6, marker = "arrowTeal", dash = "") {
  return `<path d="${d}" fill="none" stroke="${color}" stroke-width="${width}" stroke-linecap="round" stroke-linejoin="round"${dash ? ` stroke-dasharray="${dash}"` : ""} marker-end="url(#${marker})"/>`;
}

function icon(kind, cx, cy, scale = 1, color = C.navy, accent = C.teal) {
  const sw = 4.5 * scale;
  if (kind === "chat") {
    return `<g fill="none" stroke="${color}" stroke-width="${sw}" stroke-linecap="round" stroke-linejoin="round"><rect x="${cx - 34 * scale}" y="${cy - 24 * scale}" width="${68 * scale}" height="${45 * scale}" rx="${10 * scale}"/><path d="M ${cx - 14 * scale} ${cy + 21 * scale} l ${-10 * scale} ${14 * scale} l ${2 * scale} ${-16 * scale}"/><circle cx="${cx - 16 * scale}" cy="${cy - 2 * scale}" r="${3 * scale}" fill="${accent}" stroke="none"/><circle cx="${cx}" cy="${cy - 2 * scale}" r="${3 * scale}" fill="${accent}" stroke="none"/><circle cx="${cx + 16 * scale}" cy="${cy - 2 * scale}" r="${3 * scale}" fill="${accent}" stroke="none"/></g>`;
  }
  if (kind === "database") {
    return `<g fill="none" stroke="${color}" stroke-width="${sw}" stroke-linejoin="round"><ellipse cx="${cx}" cy="${cy - 22 * scale}" rx="${32 * scale}" ry="${13 * scale}" fill="${C.white}"/><path d="M ${cx - 32 * scale} ${cy - 22 * scale} v ${48 * scale} c 0 ${8 * scale} ${64 * scale} ${8 * scale} ${64 * scale} 0 v ${-48 * scale}" fill="${C.card}"/><path d="M ${cx - 32 * scale} ${cy} c 0 ${8 * scale} ${64 * scale} ${8 * scale} ${64 * scale} 0 M ${cx - 32 * scale} ${cy + 20 * scale} c 0 ${8 * scale} ${64 * scale} ${8 * scale} ${64 * scale} 0"/></g>`;
  }
  if (kind === "folder") {
    return `<g stroke="${color}" stroke-width="${sw}" stroke-linejoin="round"><path d="M ${cx - 38 * scale} ${cy - 24 * scale} h ${26 * scale} l ${10 * scale} ${10 * scale} h ${40 * scale} v ${43 * scale} h ${-74 * scale} z" fill="${C.card}"/><path d="M ${cx - 34 * scale} ${cy - 8 * scale} h ${70 * scale} l ${-7 * scale} ${37 * scale} h ${-70 * scale} z" fill="${accent}" opacity="0.75"/></g>`;
  }
  if (kind === "search") {
    return `<g fill="none" stroke="${color}" stroke-width="${sw}" stroke-linecap="round"><circle cx="${cx - 8 * scale}" cy="${cy - 8 * scale}" r="${25 * scale}"/><path d="M ${cx + 10 * scale} ${cy + 10 * scale} l ${25 * scale} ${25 * scale}" stroke="${accent}"/></g>`;
  }
  if (kind === "docs") {
    return `<g fill="${C.white}" stroke="${color}" stroke-width="${sw}" stroke-linejoin="round"><rect x="${cx - 32 * scale}" y="${cy - 30 * scale}" width="${52 * scale}" height="${62 * scale}" rx="${5 * scale}"/><rect x="${cx - 17 * scale}" y="${cy - 18 * scale}" width="${52 * scale}" height="${62 * scale}" rx="${5 * scale}"/><path d="M ${cx - 5 * scale} ${cy - 1 * scale} h ${28 * scale} M ${cx - 5 * scale} ${cy + 12 * scale} h ${28 * scale} M ${cx - 5 * scale} ${cy + 25 * scale} h ${20 * scale}" fill="none" stroke="${accent}"/></g>`;
  }
  if (kind === "chip") {
    let pins = "";
    for (const offset of [-22, -7, 8, 23]) {
      pins += `<path d="M ${cx + offset * scale} ${cy - 39 * scale} v ${10 * scale} M ${cx + offset * scale} ${cy + 29 * scale} v ${10 * scale}"/>`;
      pins += `<path d="M ${cx - 39 * scale} ${cy + offset * scale} h ${10 * scale} M ${cx + 29 * scale} ${cy + offset * scale} h ${10 * scale}"/>`;
    }
    return `<g fill="none" stroke="${color}" stroke-width="${sw}" stroke-linecap="round"><rect x="${cx - 29 * scale}" y="${cy - 29 * scale}" width="${58 * scale}" height="${58 * scale}" rx="${7 * scale}"/><rect x="${cx - 15 * scale}" y="${cy - 15 * scale}" width="${30 * scale}" height="${30 * scale}" rx="${4 * scale}" fill="${accent}" stroke="none"/>${pins}</g>`;
  }
  if (kind === "file") {
    return `<g fill="${C.white}" stroke="${color}" stroke-width="${sw}" stroke-linejoin="round" stroke-linecap="round"><path d="M ${cx - 27 * scale} ${cy - 36 * scale} h ${33 * scale} l ${22 * scale} ${22 * scale} v ${53 * scale} h ${-55 * scale} z"/><path d="M ${cx + 6 * scale} ${cy - 36 * scale} v ${22 * scale} h ${22 * scale}" fill="none"/><path d="M ${cx - 13 * scale} ${cy - 2 * scale} h ${27 * scale} M ${cx - 13 * scale} ${cy + 12 * scale} h ${27 * scale} M ${cx - 13 * scale} ${cy + 26 * scale} h ${19 * scale}" fill="none" stroke="${accent}"/></g>`;
  }
  if (kind === "clock") {
    return `<g fill="none" stroke="${color}" stroke-width="${sw}" stroke-linecap="round"><circle cx="${cx}" cy="${cy}" r="${31 * scale}"/><path d="M ${cx} ${cy - 17 * scale} v ${19 * scale} l ${14 * scale} ${9 * scale}" stroke="${accent}"/></g>`;
  }
  if (kind === "globe") {
    return `<g fill="none" stroke="${color}" stroke-width="${sw}"><circle cx="${cx}" cy="${cy}" r="${30 * scale}"/><ellipse cx="${cx}" cy="${cy}" rx="${14 * scale}" ry="${30 * scale}"/><path d="M ${cx - 28 * scale} ${cy - 10 * scale} h ${56 * scale} M ${cx - 28 * scale} ${cy + 10 * scale} h ${56 * scale}" stroke="${accent}"/></g>`;
  }
  return `<circle cx="${cx}" cy="${cy}" r="${28 * scale}" fill="${accent}" stroke="${color}" stroke-width="${sw}"/>`;
}

function base(title, subtitle = "", height = H) {
  return `<svg xmlns="http://www.w3.org/2000/svg" width="${W}" height="${height}" viewBox="0 0 ${W} ${height}">
  <defs>
    <filter id="shadow" x="-20%" y="-20%" width="140%" height="150%"><feDropShadow dx="0" dy="5" stdDeviation="6" flood-color="#0F2D4E" flood-opacity="0.13"/></filter>
    <linearGradient id="navyBand" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="#173E67"/><stop offset="1" stop-color="#0F2D4E"/></linearGradient>
    <linearGradient id="tealBand" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="#13A099"/><stop offset="1" stop-color="#087F7A"/></linearGradient>
    <linearGradient id="amberBand" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="#E8A33A"/><stop offset="1" stop-color="#CF821E"/></linearGradient>
    <marker id="arrowNavy" markerWidth="12" markerHeight="12" refX="10" refY="6" orient="auto"><path d="M 0 0 L 12 6 L 0 12 z" fill="${C.navy}"/></marker>
    <marker id="arrowTeal" markerWidth="12" markerHeight="12" refX="10" refY="6" orient="auto"><path d="M 0 0 L 12 6 L 0 12 z" fill="${C.teal2}"/></marker>
    <marker id="arrowAmber" markerWidth="12" markerHeight="12" refX="10" refY="6" orient="auto"><path d="M 0 0 L 12 6 L 0 12 z" fill="${C.amber}"/></marker>
    <marker id="arrowRed" markerWidth="12" markerHeight="12" refX="10" refY="6" orient="auto"><path d="M 0 0 L 12 6 L 0 12 z" fill="${C.red}"/></marker>
    <marker id="arrowNavySmall" markerWidth="6" markerHeight="6" refX="5" refY="3" orient="auto"><path d="M 0 0 L 6 3 L 0 6 z" fill="${C.navy}"/></marker>
    <marker id="arrowTealSmall" markerWidth="6" markerHeight="6" refX="5" refY="3" orient="auto"><path d="M 0 0 L 6 3 L 0 6 z" fill="${C.teal2}"/></marker>
    <marker id="arrowAmberSmall" markerWidth="6" markerHeight="6" refX="5" refY="3" orient="auto"><path d="M 0 0 L 6 3 L 0 6 z" fill="${C.amber}"/></marker>
    <marker id="arrowVioletSmall" markerWidth="6" markerHeight="6" refX="5" refY="3" orient="auto"><path d="M 0 0 L 6 3 L 0 6 z" fill="${C.violet}"/></marker>
    <marker id="arrowNavyFixed10" viewBox="0 0 10 10" markerWidth="10" markerHeight="10" refX="9" refY="5" orient="auto" markerUnits="userSpaceOnUse"><path d="M 1 1 L 9 5 L 1 9 z" fill="${C.navy}"/></marker>
    <marker id="arrowTealFixed10" viewBox="0 0 10 10" markerWidth="10" markerHeight="10" refX="9" refY="5" orient="auto" markerUnits="userSpaceOnUse"><path d="M 1 1 L 9 5 L 1 9 z" fill="${C.teal2}"/></marker>
    <marker id="arrowAmberFixed10" viewBox="0 0 10 10" markerWidth="10" markerHeight="10" refX="9" refY="5" orient="auto" markerUnits="userSpaceOnUse"><path d="M 1 1 L 9 5 L 1 9 z" fill="${C.amber}"/></marker>
    <marker id="arrowNavyFixed14" viewBox="0 0 14 14" markerWidth="14" markerHeight="14" refX="13" refY="7" orient="auto" markerUnits="userSpaceOnUse"><path d="M 1 1 L 13 7 L 1 13 z" fill="${C.navy}"/></marker>
    <marker id="arrowAmberFixed14" viewBox="0 0 14 14" markerWidth="14" markerHeight="14" refX="13" refY="7" orient="auto" markerUnits="userSpaceOnUse"><path d="M 1 1 L 13 7 L 1 13 z" fill="${C.amber}"/></marker>
  </defs>
  <rect width="${W}" height="${height}" fill="${C.bg}"/>
  ${text(W / 2, 64, title, { size: 54, weight: 800 })}
  ${subtitle ? text(W / 2, 104, subtitle, { size: 23, weight: 500, fill: C.slate }) : ""}
`;
}

function end() {
  return `</svg>`;
}

function laneHeader(x, y, w, label, gradient) {
  return `<rect x="${x}" y="${y}" width="${w}" height="64" rx="18" fill="url(#${gradient})"/>${text(x + w / 2, y + 43, label, { size: 30, weight: 800, fill: C.white })}`;
}

function nodeBox(x, y, w, h, label, options = {}) {
  const { fill = C.card, stroke = C.border, size = 22, iconName = "", accent = C.teal } = options;
  const lines = Array.isArray(label) ? label : [label];
  const lineHeight = 1.04;
  const firstBaseline = y + h / 2 + size * 0.34 - ((lines.length - 1) * size * lineHeight) / 2;
  let out = card(x, y, w, h, { fill, stroke, strokeWidth: 2.3, radius: 14, shadow: false });
  if (iconName) out += icon(iconName, x + 42, y + h / 2, 0.48, C.navy, accent);
  out += text(x + (iconName ? 78 : w / 2), firstBaseline, lines, {
    size,
    weight: 700,
    anchor: iconName ? "start" : "middle",
    lineHeight,
  });
  return out;
}

function figure22() {
  let svg = base(
    "Filesystem, ReFind, and Full Context Access Paths",
    "Two selective-retrieval paths construct focused evidence; Full Context bypasses external selection",
  );
  svg += card(485, 120, 630, 72, { fill: C.card2, stroke: C.navy, strokeWidth: 3, radius: 16 });
  svg += icon("chat", 535, 156, 0.5, C.navy, C.teal);
  svg += text(820, 166, "Same question and conversation history", { size: 26, weight: 750 });
  svg += pathArrow("M 800 192 V 212 H 295 V 224", C.navy, 4, "arrowNavyFixed10");
  svg += pathArrow("M 800 192 V 224", C.navy, 4, "arrowNavyFixed10");
  svg += pathArrow("M 800 192 V 212 H 1305 V 224", C.navy, 4, "arrowNavyFixed10");

  const cols = [55, 560, 1065];
  const cw = 480;
  svg += laneHeader(cols[0], 230, cw, "Filesystem-Based Memory", "tealBand");
  svg += laneHeader(cols[1], 230, cw, "ReFind-Style Retrieval", "tealBand");
  svg += laneHeader(cols[2], 230, cw, "Full Context", "amberBand");

  const ys = [315, 392, 469, 546, 623];
  const nh = 58;

  svg += nodeBox(cols[0] + 45, ys[0], 390, nh, "Organised file store", { iconName: "folder" });
  svg += nodeBox(cols[0] + 45, ys[1], 390, nh, "Search Agent", { iconName: "search" });
  svg += nodeBox(cols[0] + 45, ys[2], 390, nh, "list  •  grep  •  view", { fill: C.tealPale, stroke: C.teal, size: 21 });
  svg += nodeBox(cols[0] + 45, ys[3], 390, nh, "Selected passages", { iconName: "docs" });
  svg += nodeBox(cols[0] + 45, ys[4], 390, nh, "EvidenceBundle", { fill: C.tealPale, stroke: C.teal, iconName: "docs" });
  for (let i = 0; i < ys.length - 1; i++) {
    svg += arrow(cols[0] + 240, ys[i] + nh + 2, cols[0] + 240, ys[i + 1] - 4, C.teal2, 3.5, "arrowTealFixed10");
  }

  svg += nodeBox(cols[1] + 45, ys[0], 390, nh, "Raw dialogue + lexical index", { iconName: "database" });
  svg += nodeBox(cols[1] + 45, ys[1], 390, nh, "LLM controller formulates query", { iconName: "search", size: 20 });
  svg += nodeBox(cols[1] + 45, ys[2], 390, nh, "BM25 + session signals → RRF", { fill: C.tealPale, stroke: C.teal, size: 19 });
  svg += nodeBox(cols[1] + 45, ys[3], 390, nh, ["Local expansion + temporary notes", "repeat if evidence is insufficient"], { size: 18 });
  svg += nodeBox(cols[1] + 45, ys[4], 390, nh, "finish_search → EvidenceBundle", { fill: C.tealPale, stroke: C.teal, size: 19 });
  for (let i = 0; i < ys.length - 1; i++) {
    svg += arrow(cols[1] + 240, ys[i] + nh + 2, cols[1] + 240, ys[i + 1] - 4, C.teal2, 3.5, "arrowTealFixed10");
  }
  svg += pathArrow(`M ${cols[1] + 430} ${ys[3] + 29} H ${cols[1] + 465} V ${ys[1] + 29} H ${cols[1] + 440}`, C.teal2, 3.5, "arrowTealFixed10", "9 7");

  svg += nodeBox(cols[2] + 45, ys[0], 390, nh, "Complete raw history", { iconName: "docs", accent: C.amber });
  svg += nodeBox(cols[2] + 45, ys[1], 390, nh, "No external selector", { fill: C.amberPale, stroke: C.amber, size: 22 });
  svg += nodeBox(cols[2] + 45, ys[2], 390, nh, ["All sessions form", "one long prompt"], { iconName: "docs", accent: C.amber, size: 18 });
  svg += pill(cols[2] + 82, ys[3] + 5, 316, 50, "Bypasses EvidenceBundle", C.amber, C.amberPale, { size: 20, icon: "alert" });
  svg += text(cols[2] + 240, ys[4] + 35, ["Complete visibility", "does not guarantee correct use"], { size: 20, weight: 700, fill: C.slate, lineHeight: 1.08 });
  svg += arrow(cols[2] + 240, ys[0] + nh + 2, cols[2] + 240, ys[1] - 4, C.amber, 3.5, "arrowAmberFixed10");
  svg += arrow(cols[2] + 240, ys[1] + nh + 2, cols[2] + 240, ys[2] - 4, C.amber, 3.5, "arrowAmberFixed10");

  svg += pathArrow(`M ${cols[0] + 240} ${ys[4] + nh + 4} V 746 H 642`, C.teal2, 4.5, "arrowTealFixed10");
  svg += pathArrow(`M ${cols[1] + 240} ${ys[4] + nh + 4} V 700`, C.teal2, 4.5, "arrowTealFixed10");
  svg += pathArrow(`M ${cols[2] + 439} ${ys[2] + 29} H 1525 V 746 H 958`, C.amber, 4.5, "arrowAmberFixed10");
  svg += card(650, 708, 300, 76, { fill: C.card, stroke: C.navy, strokeWidth: 3, radius: 18 });
  svg += icon("chip", 705, 746, 0.52, C.navy, C.teal);
  svg += text(830, 756, "Answerer", { size: 28, weight: 800 });
  svg += arrow(800, 792, 800, 824, C.navy, 4, "arrowNavyFixed10");
  svg += card(650, 832, 300, 54, { fill: C.tealPale, stroke: C.teal, strokeWidth: 2.5, radius: 16, shadow: false });
  svg += text(800, 868, "Final answer", { size: 25, weight: 800 });
  return svg + end();
}

function tinyPattern(x, y, kind) {
  const navy = C.navy;
  const teal = C.teal2;
  if (kind === "single") {
    return `<circle cx="${x - 50}" cy="${y}" r="14" fill="${teal}"/><path d="M ${x - 28} ${y} H ${x + 27}" stroke="${navy}" stroke-width="3.5" marker-end="url(#arrowNavyFixed14)"/><circle cx="${x + 48}" cy="${y}" r="18" fill="${C.white}" stroke="${navy}" stroke-width="3.5"/>${text(x + 48, y + 6, "Q", { size: 17, weight: 800 })}`;
  }
  if (kind === "multi") {
    return `<circle cx="${x - 52}" cy="${y - 15}" r="12" fill="${teal}"/><circle cx="${x - 52}" cy="${y + 15}" r="12" fill="${teal}"/><path d="M ${x - 34} ${y - 15} C ${x - 8} ${y - 15}, ${x - 3} ${y}, ${x + 18} ${y}" stroke="${navy}" stroke-width="3.5" fill="none"/><path d="M ${x - 34} ${y + 15} C ${x - 8} ${y + 15}, ${x - 3} ${y}, ${x + 18} ${y}" stroke="${navy}" stroke-width="3.5" fill="none"/><path d="M ${x + 18} ${y} H ${x + 31}" stroke="${navy}" stroke-width="3.5" marker-end="url(#arrowNavyFixed14)"/><circle cx="${x + 52}" cy="${y}" r="18" fill="${C.white}" stroke="${navy}" stroke-width="3.5"/>${text(x + 52, y + 6, "Q", { size: 17, weight: 800 })}`;
  }
  if (kind === "temporal") {
    return `${icon("clock", x - 50, y, 0.42, navy, C.red)}${pathArrow(`M ${x - 28} ${y} H ${x + 28}`, C.amber, 3, "arrowAmberFixed14")}${icon("clock", x + 50, y, 0.42, navy, teal)}`;
  }
  if (kind === "open") {
    return `<circle cx="${x - 55}" cy="${y}" r="14" fill="${teal}"/>${text(x - 55, y + 7, "T", { size: 15, weight: 800, fill: C.white })}${text(x, y + 8, "+", { size: 30, weight: 800, fill: C.slate })}${icon("globe", x + 55, y, 0.48, navy, teal)}`;
  }
  return `<path d="M ${x - 65} ${y - 25} h 70 v 50 h -70 z" fill="${C.card}" stroke="${navy}" stroke-width="4" stroke-dasharray="7 5"/>${text(x - 30, y + 7, "?", { size: 28, weight: 800 })}<path d="M ${x + 28} ${y - 22} l 45 44 M ${x + 73} ${y - 22} l -45 44" stroke="${C.red}" stroke-width="7" stroke-linecap="round"/>`;
}

function figure23() {
  let svg = base(
    "LoCoMo: Multi-Session Evidence Structure",
    "Reference answers are linked to source turn IDs; the annotations are evidence locations, not full reasoning chains",
  );

  svg += card(45, 135, 1510, 345, { fill: C.card, stroke: C.navy, strokeWidth: 3, radius: 22 });
  svg += text(95, 180, "Multi-session conversation", { size: 27, weight: 800, anchor: "start" });
  const sessions = [
    { x: 85, label: "Session 1", hits: [1] },
    { x: 365, label: "Session 2", hits: [] },
    { x: 645, label: "Session 3", hits: [0, 2] },
    { x: 925, label: "…", hits: [] },
    { x: 1205, label: "Session N", hits: [1] },
  ];
  sessions.forEach((s, si) => {
    svg += card(s.x, 205, 230, 175, { fill: C.white, stroke: C.border, strokeWidth: 2.2, radius: 16, shadow: false });
    svg += `<rect x="${s.x}" y="205" width="230" height="48" rx="16" fill="${si === 3 ? C.slate : C.navy}"/><rect x="${s.x}" y="237" width="230" height="16" fill="${si === 3 ? C.slate : C.navy}"/>`;
    svg += text(s.x + 115, 238, s.label, { size: 23, weight: 800, fill: C.white });
    if (si === 3) {
      svg += text(s.x + 115, 323, "Many sessions", { size: 22, weight: 650, fill: C.slate });
    } else {
      [0, 1, 2].forEach((turn) => {
        const ty = 282 + turn * 34;
        const hit = s.hits.includes(turn);
        svg += `<circle cx="${s.x + 28}" cy="${ty}" r="9" fill="${hit ? C.teal : C.border}"/>`;
        svg += `<line x1="${s.x + 48}" y1="${ty}" x2="${s.x + 195}" y2="${ty}" stroke="${hit ? C.teal : C.border}" stroke-width="${hit ? 6 : 4}" stroke-linecap="round"/>`;
        if (hit) svg += text(s.x + 205, ty + 6, `t${turn + 1}`, { size: 16, weight: 800, fill: C.teal });
      });
    }
  });
  sessions.slice(0, -1).forEach((s, i) => {
    svg += arrow(s.x + 235, 292, sessions[i + 1].x - 8, 292, C.navy, 4, "arrowNavySmall");
  });
  svg += pill(480, 405, 330, 52, "Annotated source turn IDs", C.teal, C.tealPale, { size: 20, icon: "check" });
  svg += arrow(825, 431, 920, 431, C.teal, 4, "arrowTealFixed10");
  svg += card(935, 397, 250, 68, { fill: C.white, stroke: C.navy, strokeWidth: 2.5, radius: 15, shadow: false });
  svg += text(1060, 440, "Question", { size: 24, weight: 800 });
  svg += arrow(1192, 431, 1270, 431, C.navy, 4.5, "arrowNavySmall");
  svg += card(1280, 397, 235, 68, { fill: C.tealPale, stroke: C.teal, strokeWidth: 2.5, radius: 15, shadow: false });
  svg += text(1398, 440, "Reference answer", { size: 21, weight: 800 });

  svg += text(65, 540, "Question categories encode different evidence requirements", { size: 27, weight: 800, anchor: "start" });
  const cats = [
    ["Single-hop", "One source", "single", C.tealPale, C.teal],
    ["Multi-hop", "Multiple sessions", "multi", C.tealPale, C.teal],
    ["Temporal", "Order or update", "temporal", C.amberPale, C.amber],
    ["Open-domain", "Dialogue + knowledge", "open", C.violetPale, C.violet],
    ["Adversarial", "False premise", "adversarial", C.redPale, C.red],
  ];
  const catW = 284;
  const catGap = 24;
  cats.forEach(([name, detail, kind, fill, stroke], index) => {
    const x = 42 + index * (catW + catGap);
    svg += card(x, 575, catW, 245, { fill, stroke, strokeWidth: 2.5, radius: 18 });
    svg += text(x + catW / 2, 621, name, { size: 26, weight: 800 });
    svg += tinyPattern(x + catW / 2, 689, kind);
    svg += text(x + catW / 2, 761, detail, { size: 20, weight: 650, fill: C.slate });
    if (name === "Adversarial") {
      svg += pill(x + 31, 778, 222, 34, "Excluded from Main-60", C.red, C.white, { size: 15 });
    }
  });
  svg += text(800, 866, "Main-60 uses the four non-adversarial categories as one unified test set", { size: 23, weight: 700, fill: C.navy });
  return svg + end();
}

const outputs = [
  ["figure-2-2-filesystem-refind-full-context-access-paths", figure22()],
  ["figure-2-3-locomo-multi-session-evidence-structure", figure23()],
];

async function main() {
  for (const [stem, svg] of outputs) {
    const svgPath = path.join(OUT, `${stem}.svg`);
    const pngPath = path.join(OUT, `${stem}.png`);
    fs.writeFileSync(svgPath, svg, "utf8");
    await sharp(Buffer.from(svg))
      .resize(1672, 941, { fit: "fill" })
      .flatten({ background: C.bg })
      .png({ compressionLevel: 9, adaptiveFiltering: true })
      .toFile(pngPath);
  }

  const lines = outputs
    .flatMap(([stem]) => [`${stem}.png`, `${stem}.svg`])
    .map((name) => {
      const bytes = fs.readFileSync(path.join(OUT, name));
      const digest = crypto.createHash("sha256").update(bytes).digest("hex");
      return `${digest}  ${name}`;
    });
  fs.writeFileSync(path.join(OUT, "SHA256SUMS"), `${lines.join("\n")}\n`, "utf8");
}

main().catch((error) => {
  console.error(error);
  process.exitCode = 1;
});
